fn old(index: &DeclarationIndex, ty: &ResolvedType) -> Option<TypeFlags> {
    index.type_facts_owned_key_oracle(ty).as_ref().map(TypeFlags::from)
}
#[test]
fn leaf_flags_preserve_literal_facts_and_current_cached_precedence_without_query_allocations() {
    let mut index = DeclarationIndex::default();
    let types = leaves();
    for (ty, copy, needs_drop) in &types {
        let expected = Some(TypeFlags {
            copy: *copy,
            contains_resource: false,
            sized: true,
            needs_drop: *needs_drop,
        });
        assert_eq!(old(&index, ty), expected);
        assert_eq!(index.type_flags(ty), expected);
    }
    let (_, observed) = crate::test_allocation_observer::measure(|| {
        for _ in 0..128 {
            for (ty, copy, needs_drop) in &types {
                assert_eq!(
                    index.type_flags(ty),
                    Some(TypeFlags {
                        copy: *copy,
                        contains_resource: false,
                        sized: true,
                        needs_drop: *needs_drop
                    })
                );
            }
        }
    });
    assert!(!observed.invalid);
    assert_eq!(
        (observed.allocations, observed.allocated, observed.live),
        (0, 0, 0)
    );
    let (_, owned) = crate::test_allocation_observer::measure(|| {
        for (ty, _, _) in &types {
            std::hint::black_box(index.type_facts_owned_key_oracle(ty));
        }
    });
    assert!(!owned.invalid && owned.allocations > 0 && owned.allocated > 0);
    assert_eq!(owned.live, 0);
    // A cached entry takes precedence even when independently invalid. The
    // ordinary HIR validator, not this projection, owns cache-fact validation.
    for (ty, _, _) in types
        .iter()
        .chain(std::iter::once(&(ResolvedType::Never, false, false)))
    {
        let key = ty.identity_key();
        index.type_facts_by_id.insert(
            key.clone(),
            TypeFacts {
                copy: false,
                contains_resource: true,
                sized: false,
                needs_drop: true,
                layout_key: "hostile layout".into(),
            },
        );
        assert_eq!(index.type_flags(ty), old(&index, ty));
        index.type_facts_by_id.get_mut(&key).unwrap().layout_key =
            "different layout with unchanged flags".into();
        let (_, observed) = crate::test_allocation_observer::measure(|| {
            assert_eq!(
                index.type_flags(ty),
                Some(TypeFlags {
                    copy: false,
                    contains_resource: true,
                    sized: false,
                    needs_drop: true
                })
            )
        });
        assert!(!observed.invalid);
        assert_eq!(
            (observed.allocations, observed.allocated, observed.live),
            (0, 0, 0)
        );
        index.type_facts_by_id.remove(&key);
    }
    assert_eq!(index.type_flags(&ResolvedType::Never), None);
}
#[test]
fn dynamic_flags_keep_owned_layout_unknown_generic_and_malformed_fallback_verdicts() {
    let source = crate::check(
        r#"module facts;
@id("leaf") record Leaf {@id("leaf.text") text:string,}
@id("row") record Row {@id("row.leaf") leaf:Leaf,@id("row.bytes") bytes:Bytes,@id("row.n") n:i64,}
@id("main") fn main()->i64 {0}
"#,
        "flag-facts.spx",
    )
    .unwrap();
    let program = crate::hir::resolve(&source).unwrap();
    crate::hir::validate(&program).unwrap();
    let index = &program.declarations;
    let types = vec![
        ResolvedType::ArrayU8(0),
        ResolvedType::ArrayU8(65536),
        ResolvedType::Nominal {
            declaration: DeclarationId::new("row"),
            arguments: vec![],
        },
        ResolvedType::Nominal {
            declaration: DeclarationId::new("missing"),
            arguments: vec![],
        },
        ResolvedType::Nominal {
            declaration: DeclarationId::new("row"),
            arguments: vec![ResolvedType::I64],
        },
        ResolvedType::TypeParameter {
            owner: DeclarationId::new("missing"),
            index: 0,
        },
        ResolvedType::Function {
            parameters: vec![ResolvedType::I64],
            result: Box::new(ResolvedType::I64),
        },
        ResolvedType::Function {
            parameters: vec![ResolvedType::Never],
            result: Box::new(ResolvedType::I64),
        },
    ];
    for ty in &types {
        assert_eq!(index.type_flags(ty), old(index, ty), "{ty:?}");
    }
    assert_eq!(
        index.type_flags(&types[2]),
        Some(TypeFlags {
            copy: false,
            contains_resource: false,
            sized: true,
            needs_drop: true
        })
    );
    assert!(index.type_flags(&types[3]).is_none());
    let cached = index.type_facts_by_id.clone();
    let leaf_types = leaves();
    let (_, warm) = crate::test_allocation_observer::measure(|| {
        for (ty, copy, needs_drop) in &leaf_types {
            assert_eq!(
                index.type_flags(ty),
                Some(TypeFlags {
                    copy: *copy,
                    contains_resource: false,
                    sized: true,
                    needs_drop: *needs_drop,
                })
            );
        }
    });
    assert!(!warm.invalid);
    assert_eq!((warm.allocations, warm.allocated, warm.live), (0, 0, 0));
    for (ty, _, _) in leaves() {
        assert_eq!(index.type_flags(&ty), old(index, &ty));
    }
    assert_eq!(
        index.type_facts_by_id, cached,
        "queries publish no new memo or layout facts"
    );
}

#[test]
fn dynamic_cached_flags_remove_only_retained_layout_clones_through_drop() {
    // Current cached facts are intentionally independent of language constants:
    // the full owned API remains the oracle even for hostile layout/flag facts.
    let mut index = DeclarationIndex::default();
    let ty = ResolvedType::Nominal {
        declaration: DeclarationId::new("current.row"),
        arguments: vec![ResolvedType::I64],
    };
    let key = ty.identity_key();
    const LAYOUT: &str = "retained-layout-payload";
    const QUERIES: usize = 32;
    index.type_facts_by_id.insert(
        key,
        TypeFacts {
            copy: true,
            contains_resource: true,
            sized: false,
            needs_drop: true,
            layout_key: LAYOUT.to_owned(),
        },
    );
    let expected = Some(TypeFlags {
        copy: true,
        contains_resource: true,
        sized: false,
        needs_drop: true,
    });
    let (_, owned) = crate::test_allocation_observer::measure(|| {
        for _ in 0..QUERIES {
            let facts = std::hint::black_box(index.type_facts_owned_key_oracle(&ty));
            assert_eq!(facts.as_ref().map(TypeFlags::from), expected);
            drop(facts);
        }
    });
    let (_, borrowed) = crate::test_allocation_observer::measure(|| {
        for _ in 0..QUERIES {
            assert_eq!(index.type_flags(&ty), expected);
        }
    });
    // Independent saved key-only construction isolates every original scratch
    // request; the streamed query now removes those AND the owned layout clone.
    let (_, keys) = crate::test_allocation_observer::measure(|| {
        for _ in 0..QUERIES { drop(std::hint::black_box(ty.identity_key())); }
    });
    assert!(!owned.invalid && !borrowed.invalid && !keys.invalid);
    assert_eq!(owned.live, 0);
    assert_eq!(keys.live, 0);
    assert_eq!(owned.allocated, owned.freed);
    assert_eq!(keys.allocated, keys.freed);
    assert_eq!(owned.allocations, keys.allocations + QUERIES);
    assert_eq!(owned.allocated, keys.allocated + QUERIES * 23);
    assert_eq!((borrowed.allocations, borrowed.reallocations, borrowed.allocated, borrowed.freed, borrowed.live), (0, 0, 0, 0, 0));
    assert_eq!(LAYOUT.len(), 23);
    assert_eq!(index.type_flags(&ty), old(&index, &ty));
}

//! Exact, authority-free callable identities for Function Value v1.
use super::{
    DeclarationId, OwnershipMode, ResolvedExpr, ResolvedExprKind, ResolvedFunction,
    ResolvedProgram, ResolvedType,
};
use crate::diagnostic::Diagnostic;
use std::collections::BTreeSet;

pub fn scalar(ty: &ResolvedType) -> bool {
    super::nodes::is_scalar_resolved_type(ty)
}
pub fn is_signature(ty: &ResolvedType) -> bool {
    matches!(ty, ResolvedType::Function { parameters, result } if parameters.len() <= 8 && parameters.iter().all(scalar) && scalar(result))
}
/// Internal helpers may transport scalar callable values; this does not admit
/// those signatures at an imported or selected public boundary.
pub(crate) fn private_helper_signature(function: &ResolvedFunction) -> bool {
    let slot = |ty: &ResolvedType| {
        scalar(ty) || is_signature(ty) || ty.is_once_function() || ty.is_mut_function()
    };
    function.effects.is_empty()
        && function.params.len() <= 8
        && function.params.iter().all(|p| {
            slot(&p.ty)
                && p.ownership
                    == if p.ty.is_once_function() || p.ty.is_mut_function() {
                        OwnershipMode::Own
                    } else {
                        OwnershipMode::Value
                    }
        })
        && slot(&function.return_type)
        && (function.params.iter().any(|p| is_signature(&p.ty))
            || is_signature(&function.return_type)
            || function.return_type.is_once_function()
            || function.return_type.is_mut_function()
            || function
                .params
                .iter()
                .any(|p| p.ty.is_once_function() || p.ty.is_mut_function()))
}
pub fn signature(function: &ResolvedFunction) -> Option<ResolvedType> {
    (function.effects.is_empty()
        && function.params.len() <= 8
        && function
            .params
            .iter()
            .all(|p| p.ownership == OwnershipMode::Value && scalar(&p.ty))
        && scalar(&function.return_type))
    .then(|| ResolvedType::Function {
        parameters: function.params.iter().map(|p| p.ty.clone()).collect(),
        result: Box::new(function.return_type.clone()),
    })
}
pub(crate) fn walk<'a>(function: &'a ResolvedFunction, mut visit: impl FnMut(&'a ResolvedExpr)) {
    let mut pending = function
        .requires
        .iter()
        .chain(std::iter::once(&function.body))
        .chain(&function.ensures)
        .collect::<Vec<_>>();
    while let Some(expr) = pending.pop() {
        visit(expr);
        super::push_resolved_expression_children_in_authored_order(expr, &mut pending);
    }
}
pub fn target_universe(program: &ResolvedProgram) -> Vec<&ResolvedFunction> {
    let mut ids = BTreeSet::new();
    for f in program.functions.iter().chain(
        program
            .function_instances
            .iter()
            .map(|instance| &instance.function),
    ) {
        walk(f, |e| {
            if let ResolvedExprKind::FunctionReference { target } = &e.kind {
                ids.insert(target.clone());
            }
        });
    }
    let mut functions = program
        .functions
        .iter()
        .filter(|f| ids.contains(&f.id))
        .collect::<Vec<_>>();
    functions.sort_by(|a, b| a.id.cmp(&b.id));
    functions
}
pub fn compatible_targets<'a>(
    program: &'a ResolvedProgram,
    ty: &ResolvedType,
) -> Vec<&'a ResolvedFunction> {
    target_universe(program)
        .into_iter()
        .filter(|f| signature(f).as_ref() == Some(ty))
        .collect()
}
pub fn requires_function_values(program: &ResolvedProgram) -> bool {
    program
        .functions
        .iter()
        .chain(
            program
                .function_instances
                .iter()
                .map(|instance| &instance.function),
        )
        .any(function_uses_value)
        || program.function_templates.iter().any(template_uses_value)
}
pub(crate) fn validate_reference(
    program: &ResolvedProgram,
    target: &DeclarationId,
    ty: &ResolvedType,
) -> Result<(), Diagnostic> {
    let target = program
        .functions
        .iter()
        .find(|f| f.id == *target)
        .ok_or_else(|| error("function reference does not name a local monomorphic declaration"))?;
    if signature(target).as_ref() != Some(ty) {
        return Err(error(
            "function reference has an ineligible or mismatched signature",
        ));
    }
    Ok(())
}
pub(crate) fn validate_invocation(expression: &ResolvedExpr) -> Result<(), Diagnostic> {
    validate_invocation_scoped(expression, None)
}
pub(crate) fn validate_invocation_scoped(
    expression: &ResolvedExpr,
    owner: Option<(&DeclarationId, usize)>,
) -> Result<(), Diagnostic> {
    let ResolvedExprKind::Invoke { callable, args } = &expression.kind else {
        return Err(error("expected invocation"));
    };
    if callable.ty.is_mut_function() {
        return if callable.ownership == OwnershipMode::Own
            && matches!(args.as_slice(), [argument] if argument.ty == ResolvedType::I64 && argument.ownership == OwnershipMode::Value)
            && expression.ty == ResolvedType::I64
            && expression.ownership == OwnershipMode::Value
            && matches!(&callable.kind, ResolvedExprKind::Place(p) if p.projections.is_empty())
        {
            Ok(())
        } else {
            Err(error(
                "mutable invocation requires its direct unique receiver and one i64 argument",
            ))
        };
    }
    if callable.ty.is_once_function() {
        return if callable.ownership == OwnershipMode::Own
            && args.is_empty()
            && expression.ty == ResolvedType::I64
            && expression.ownership == OwnershipMode::Value
            && matches!(&callable.kind, ResolvedExprKind::Place(p) if p.projections.is_empty())
        {
            Ok(())
        } else {
            Err(error("affine invocation must consume its exact owner once"))
        };
    }
    let ResolvedType::Function { parameters, result } = &callable.ty else {
        return Err(error("invocation target is not a function value"));
    };
    if !matches!(&callable.kind,ResolvedExprKind::Place(place) if place.projections.is_empty())
        || !(is_signature(&callable.ty)
            || owner.is_some_and(|(owner, count)| {
                super::generic_collection::callback(&callable.ty, owner, count)
            }))
        || callable.ownership != OwnershipMode::Value
        || args.len() != parameters.len()
        || args
            .iter()
            .zip(parameters)
            .any(|(a, p)| a.ty != *p || a.ownership != OwnershipMode::Value)
        || expression.ty != **result
        || expression.ownership != OwnershipMode::Value
    {
        return Err(error("invocation signature, argument or result mismatch"));
    }
    Ok(())
}
pub(crate) fn error(message: &str) -> Diagnostic {
    Diagnostic::io("SPX-H006", message)
}

pub(crate) mod resolve;

pub(crate) static INVOKE_ID: std::sync::LazyLock<DeclarationId> = std::sync::LazyLock::new(|| {
    DeclarationId::compiler(crate::hir::CompilerDeclaration::FunctionInvoke)
});
pub(crate) fn invocation_params(
    expression: &ResolvedExpr,
) -> Result<Vec<super::ResolvedParam>, Diagnostic> {
    validate_invocation(expression)?;
    let ResolvedExprKind::Invoke { callable, .. } = &expression.kind else {
        unreachable!()
    };
    let parameters: &[ResolvedType] = match &callable.ty {
        ResolvedType::Function { parameters, .. } => parameters,
        ResolvedType::MutFunctionI64 => &[ResolvedType::I64],
        _ => unreachable!(),
    };
    Ok(parameters
        .iter()
        .enumerate()
        .map(|(index, ty)| super::ResolvedParam {
            id: super::ValueId::intrinsic_parameter(INVOKE_ID.as_str(), index),
            name: format!("arg{index}"),
            ty: ty.clone(),
            ownership: OwnershipMode::Value,
            span: expression.span,
        })
        .collect())
}

pub(crate) fn validate_program(program: &ResolvedProgram) -> Result<(), Diagnostic> {
    super::closure::mutable::validate_uses(program)?;
    super::closure::borrowed::validate_uses(program)?;
    if !requires_function_values(program) {
        return Ok(());
    }
    if target_universe(program).len() + super::closure::inventory(program).len() > 256 {
        return Err(error(
            "function value target universe exceeds 256 declarations",
        ));
    }
    use super::FunctionExecutionId;
    let mut edges =
        std::collections::BTreeMap::<FunctionExecutionId, BTreeSet<FunctionExecutionId>>::new();
    let closure_functions = super::closure::inventory(program)
        .into_iter()
        .map(|expression| super::closure::closure_function(program, expression))
        .collect::<Result<Vec<_>, _>>()?;
    let functions = program
        .functions
        .iter()
        .chain(&closure_functions)
        .map(|function| {
            (
                FunctionExecutionId::Monomorphic(function.id.clone()),
                function,
            )
        })
        .chain(program.function_instances.iter().map(|instance| {
            (
                FunctionExecutionId::Generic(instance.id.clone()),
                &instance.function,
            )
        }));
    for (execution, f) in functions {
        let mut targets = BTreeSet::new();
        walk(f, |e| match &e.kind {
            ResolvedExprKind::Call {
                callee, instance, ..
            } => {
                targets.insert(
                    instance
                        .as_ref()
                        .map(|instance| FunctionExecutionId::Generic(instance.clone()))
                        .unwrap_or_else(|| FunctionExecutionId::Monomorphic(callee.clone())),
                );
            }
            ResolvedExprKind::Invoke { callable, .. } => {
                targets.extend(
                    super::closure::inventory(program)
                        .into_iter()
                        .filter(|closure| closure.ty == callable.ty)
                        .map(|closure| {
                            FunctionExecutionId::Monomorphic(super::closure::closure_id(
                                &closure.id,
                            ))
                        }),
                );
                targets.extend(
                    compatible_targets(program, &callable.ty)
                        .into_iter()
                        .map(|target| FunctionExecutionId::Monomorphic(target.id.clone())),
                );
            }
            _ => {}
        });
        edges.insert(execution, targets);
    }
    for root in edges.keys() {
        let mut visited = BTreeSet::new();
        let mut pending = edges[root].iter().collect::<Vec<_>>();
        while let Some(next) = pending.pop() {
            if next == root {
                return Err(error(
                    "function value candidate dependencies contain a cycle",
                ));
            }
            if visited.insert(next) {
                if let Some(children) = edges.get(next) {
                    pending.extend(children);
                }
            }
        }
    }
    Ok(())
}

pub(crate) fn function_uses_value(f: &ResolvedFunction) -> bool {
    let mut found = matches!(
        f.return_type,
        ResolvedType::Function { .. }
            | ResolvedType::OnceFunction
            | ResolvedType::OnceFunctionI64
            | ResolvedType::OnceFunctionI64Pair
            | ResolvedType::MutFunctionI64
    ) || f.params.iter().any(|p| {
        matches!(
            p.ty,
            ResolvedType::Function { .. }
                | ResolvedType::OnceFunction
                | ResolvedType::OnceFunctionI64
                | ResolvedType::OnceFunctionI64Pair
                | ResolvedType::MutFunctionI64
        )
    });
    walk(f, |e| {
        found |= matches!(
            e.kind,
            ResolvedExprKind::Closure { .. }
                | ResolvedExprKind::FunctionReference { .. }
                | ResolvedExprKind::Invoke { .. }
        )
    });
    found
}

