pub(crate) fn template_uses_value(template: &super::ResolvedFunctionTemplate) -> bool {
    let mut pending = template
        .requires
        .iter()
        .chain(std::iter::once(&template.body))
        .chain(&template.ensures)
        .collect::<Vec<_>>();
    if matches!(template.return_type, ResolvedType::Function { .. })
        || template.params.iter().any(|p| {
            matches!(
                p.ty,
                ResolvedType::Function { .. }
                    | ResolvedType::OnceFunction
                    | ResolvedType::OnceFunctionI64
                    | ResolvedType::OnceFunctionI64Pair
                    | ResolvedType::MutFunctionI64
            )
        })
    {
        return true;
    }
    while let Some(expression) = pending.pop() {
        if matches!(
            expression.kind,
            ResolvedExprKind::Closure { .. }
                | ResolvedExprKind::FunctionReference { .. }
                | ResolvedExprKind::Invoke { .. }
        ) {
            return true;
        }
        super::push_resolved_expression_children_in_authored_order(expression, &mut pending);
    }
    false
}

pub(crate) fn cleanup_call(
    expression: &ResolvedExpr,
) -> Result<
    (
        &'static DeclarationId,
        &[ResolvedExpr],
        Vec<super::ResolvedParam>,
    ),
    Diagnostic,
> {
    if let Some((callee, args)) = super::closure::once::call(expression) {
        return Ok((
            callee,
            args,
            super::closure::once::params(callee).expect("closed affine call"),
        ));
    }
    let ResolvedExprKind::Invoke { args, .. } = &expression.kind else {
        return Err(error("missing callable cleanup boundary"));
    };
    Ok((&INVOKE_ID, args, invocation_params(expression)?))
}

//! HIR type-level data model.
//!
//! Resolved types, type facts, ownership modes, and the declaration
//! nodes (types, interfaces, imports, functions) the resolver emits.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crate::ast::{MatchMode, ParamMode, Span};
use crate::cleanup::CleanupInventory;
use crate::cleanup_plan::CleanupPlan;
use crate::loan_plan::LoanPlan;

use super::expr_nodes::ResolvedExpr;
use super::ids::{DeclarationId, ExpressionId, FunctionInstanceId, ValueId};
use super::{DeclarationIndex, PlaceProjection};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DeclarationKind {
    Resource,
    ResourceDrop,
    Record,
    Field,
    Class,
    Variant,
    VariantCase,
    CaseField,
    Interface,
    Import,
    Function,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum IdentityOrigin {
    Explicit,
    Automatic,
    CompilerOwned,
}

impl IdentityOrigin {
    pub fn text(self) -> &'static str {
        match self {
            Self::Explicit => "explicit",
            Self::Automatic => "automatic",
            Self::CompilerOwned => "compiler_owned",
        }
    }

    pub fn is_persistent(self) -> bool {
        matches!(self, Self::Explicit | Self::CompilerOwned)
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Declaration {
    pub id: DeclarationId,
    pub name: String,
    pub kind: DeclarationKind,
    pub identity_origin: IdentityOrigin,
    pub owner: Option<DeclarationId>,
}

/// Authenticated origin class for one non-escaping byte-slice root.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ByteSliceRootKind {
    /// A symbolic function-parameter root. Callers substitute the argument's
    /// existing root; only a concrete host entry turns it into external input.
    FunctionParameter,
    /// The exact decoded literal expression in the held checked module image.
    /// `root` identifies a scoped descriptor; `producer` authenticates the literal.
    SourceExprStatic,
    OwnedBytes,
    /// Exact indexed field of a borrowed, generation-protected owned Vec.
    OwnedVectorField,
    OwnedVectorStringSlot,
    /// Fused `str_as_bytes(string_as_str(owner))` over one exact owned
    /// String root. The fused HIR operation retains the root String identity.
    OwnedString,
    FixedArray,
    BorrowedStr,
    /// The one immutable argument arena owned by the enclosing command
    /// invocation. Every `arg_utf8` view authenticates this same root.
    CommandArguments,
    /// Current chunk in the invocation-scoped reusable streaming reader buffer.
    StdinStreamReader,
}

/// A symbolic extent deliberately independent of the compiler host's pointer
/// width. External lengths are checked as semantic u64 values at invocation.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ByteSliceExtent {
    Constant(u64),
    ParameterLength,
    ValueLength,
}

/// One authenticated dynamic half-open subrange step. Steps are stored from
/// the original root toward the current view, so nested named ranges form a
/// bounded acyclic derivation chain without inventing a new root identity.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ByteSliceRangeStep {
    pub source: ValueId,
    pub producer: ExpressionId,
    pub start: ExpressionId,
    pub end: ExpressionId,
}

/// Stable element/field identity and the exact once-evaluated index child.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct VectorFieldProvenance {
    pub element: ResolvedType,
    pub field: DeclarationId,
    pub index: ExpressionId,
}

/// Exact provenance for a byte view. Legacy views retain a complete symbolic
/// root (`offset = 0`, `length = root length`). The additive projected-field
/// profile retains one stable field-ID projection and its authenticated type;
/// aliases and ranges preserve those facts rather than minting a new root.
/// Host boundaries alone bind external parameter symbols to input storage.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ByteSliceProvenance {
    /// Present only for a checked indexed Vec element field.
    pub vector_field: Option<Box<VectorFieldProvenance>>,
    pub root: ValueId,
    /// Exact stable-ID path from `root` to the borrowed storage. Empty retains
    /// the byte-for-byte legacy root provenance carried through Graph v23.
    pub projections: Vec<PlaceProjection>,
    /// Independently resolved type at the end of `projections`.
    pub projected_type: ResolvedType,
    pub root_kind: ByteSliceRootKind,
    pub root_length: ByteSliceExtent,
    pub offset: ByteSliceExtent,
    pub length: ByteSliceExtent,
    /// The authenticated compiler-owned view expression, absent only for a
    /// symbolic external parameter root.
    pub producer: Option<ExpressionId>,
    /// Dynamic range steps relative to each immediately preceding view.
    /// Empty preserves the exact whole-root v17-v19 meaning.
    pub ranges: Vec<ByteSliceRangeStep>,
}

#[derive(Clone, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum ResolvedType {
    /// Compiler-owned absence of normal completion; never a stored/ABI value.
    Never,
    /// A retained affine zero-argument, i64-result callable.
    OnceFunction,
    OnceFunctionI64,
    OnceFunctionI64Pair,
    /// Same-thread transactional i64 callback; unlike ordinary function
    /// values it owns one mutable receiver state cell.
    MutFunctionI64,
    Function {
        parameters: Vec<ResolvedType>,
        result: Box<ResolvedType>,
    },
    Unit,
    I64,
    /// A checked signed 32-bit integer.
    I32,
    /// One Unicode scalar value.
    Char,
    /// One unsigned 8-bit integer value.
    U8,
    /// A target-independent checked unsigned 64-bit semantic integer.
    Usize,
    /// Inline Copy byte storage with exact target-independent length.
    ArrayU8(u32),
    /// IEEE-754 single precision.
    F32,
    /// IEEE-754 double precision.
    F64,
    Bool,
    /// An owned heap UTF-8 string value; never `Copy`.
    String,
    /// Uniquely owned immutable bytes. This needs drop but is not a resource.
    Bytes,
    /// A non-owning UTF-8 view rooted in the current invocation.
    Str,
    /// A non-owning byte view rooted in the current invocation.
    SliceU8,
    /// String Collections v1: the uniquely owned `Map<string, i64>` carrier.
    /// It needs drop, is never `Copy`, and is admitted only for local
    /// bindings threaded through the compiler-owned `map_*` operations.
    StringMap,
    TypeParameter {
        owner: DeclarationId,
        index: u32,
    },
    Nominal {
        declaration: DeclarationId,
        arguments: Vec<ResolvedType>,
    },
}

impl ResolvedType {
    pub fn is_callable(&self) -> bool {
        self.is_once_function() || self.is_mut_function() || matches!(self, Self::Function { .. })
    }

    pub fn is_mut_function(&self) -> bool {
        matches!(self, Self::MutFunctionI64)
    }

    pub fn is_once_function(&self) -> bool {
        matches!(
            self,
            Self::OnceFunction | Self::OnceFunctionI64 | Self::OnceFunctionI64Pair
        )
    }

    pub fn is_compiler_i64_result(&self) -> bool {
        matches!(self, Self::Nominal { declaration, arguments }
            if declaration.as_str() == crate::prelude::RESULT_ID
                && arguments == &[Self::I64, Self::I64])
    }

    /// Canonical ownership classification shared by the resolver, cleanup
    /// builder, hostile validator, and backends. Unique ownership is not the
    /// same fact as containing an opaque resource.
    pub fn is_uniquely_owned(&self) -> bool {
        matches!(
            self,
            Self::String
                | Self::Bytes
                | Self::OnceFunction
                | Self::OnceFunctionI64
                | Self::OnceFunctionI64Pair
                | Self::MutFunctionI64
        ) || crate::map_ops::is_collection(self)
    }
    pub fn is_compiler_byte_option(&self) -> bool {
        matches!(
            self,
            Self::Nominal {
                declaration,
                arguments,
            } if declaration.as_str() == crate::prelude::OPTION_ID
                && arguments.as_slice() == [ResolvedType::U8]
        )
    }

    pub fn nominal_id(&self) -> Option<&DeclarationId> {
        match self {
            Self::Nominal { declaration, .. } => Some(declaration),
            Self::Function { .. }
            | Self::OnceFunction
            | Self::OnceFunctionI64
            | Self::OnceFunctionI64Pair
            | Self::MutFunctionI64
            | Self::Never
            | Self::Unit
            | Self::I64
            | Self::I32
            | Self::Char
            | Self::U8
            | Self::Usize
            | Self::ArrayU8(_)
            | Self::F32
            | Self::F64
            | Self::Bool
            | Self::String
            | Self::Bytes
            | Self::Str
            | Self::SliceU8
            | Self::StringMap
            | Self::TypeParameter { .. } => None,
        }
    }

    /// A name-independent key suitable as an input to future layout hashing.
    pub fn identity_key(&self) -> String {
        // Zero-argument nominal keys need no traversal or child-key storage.
        // Keep the exact length-delimited encoding used by the general path.
        if let Self::Nominal {
            declaration,
            arguments,
        } = self
        {
            if arguments.is_empty() {
                return format!("nominal:{}:{}:0:", declaration.as_str().len(), declaration);
            }
        }
        enum Frame<'a> {
            Enter(&'a ResolvedType),
            Finish(&'a DeclarationId, usize),
            FinishFunction(usize),
        }
        let mut frames = vec![Frame::Enter(self)];
        let mut keys = Vec::<String>::new();
        while let Some(frame) = frames.pop() {
            match frame {
                Frame::Enter(ty) => match ty {
                    Self::Function { parameters, result } => {
                        frames.push(Frame::FinishFunction(parameters.len()));
                        frames.push(Frame::Enter(result));
                        frames.extend(parameters.iter().rev().map(Frame::Enter));
                    }
                    Self::OnceFunction => keys.push("fn-once:bytes:i64:v1".to_owned()),
                    Self::OnceFunctionI64 => keys.push("fn-once:bytes+i64:i64:v2".to_owned()),
                    Self::OnceFunctionI64Pair => {
                        keys.push("fn-once:bytes+i64+i64:i64:v3".to_owned())
                    }
                    Self::MutFunctionI64 => keys.push("fn-mut:i64+i64:i64:v1".to_owned()),
                    Self::Never => keys.push("never:lexical-exit:v1".to_owned()),
                    Self::Unit => keys.push("unit".to_owned()),
                    Self::I64 => keys.push("i64".to_owned()),
                    Self::I32 => keys.push("i32".to_owned()),
                    Self::Char => keys.push("char".to_owned()),
                    Self::U8 => keys.push("u8".to_owned()),
                    Self::Usize => keys.push("usize".to_owned()),
                    Self::ArrayU8(length) => keys.push(format!("array:u8:{length}")),
                    Self::F32 => keys.push("f32".to_owned()),
                    Self::F64 => keys.push("f64".to_owned()),
                    Self::Bool => keys.push("bool".to_owned()),
                    Self::String => keys.push("string".to_owned()),
                    Self::Bytes => keys.push("bytes".to_owned()),
                    Self::Str => keys.push("str".to_owned()),
                    Self::SliceU8 => keys.push("slice-u8".to_owned()),
                    Self::StringMap => keys.push("map:string:i64:v1".to_owned()),
                    Self::TypeParameter { owner, index } => keys.push(format!(
                        "parameter:{}:{}:{index}",
                        owner.as_str().len(),
                        owner
                    )),
                    Self::Nominal {
                        declaration,
                        arguments,
                    } => {
                        frames.push(Frame::Finish(declaration, arguments.len()));
                        frames.extend(arguments.iter().rev().map(Frame::Enter));
                    }
                },
                Frame::FinishFunction(count) => {
                    let split = keys
                        .len()
                        .checked_sub(count + 1)
                        .expect("function key children retained");
                    let mut key = format!("function:v1:{count}:");
                    for child in keys.drain(split..) {
                        write!(key, "{}:{child}", child.len()).expect("string write");
                    }
                    keys.push(key);
                }
                Frame::Finish(declaration, count) => {
                    let split = keys
                        .len()
                        .checked_sub(count)
                        .expect("type-key traversal has one result per argument");
                    let mut encoded = crate::bounded_output::CappedString::new();
                    for key in keys.drain(split..) {
                        write!(encoded, "{}:{key}", key.len())
                            .expect("writing to a string cannot fail");
                    }
                    keys.push(format!(
                        "nominal:{}:{}:{}:{}",
                        declaration.as_str().len(),
                        declaration,
                        count,
                        encoded.into_string()
                    ));
                }
            }
        }
        keys.pop().expect("a type always produces an identity key")
    }
}

