pub(crate) fn admitted_owned_byte_prelude_instance(
    declaration: &DeclarationId,
    arguments: &[ResolvedType],
) -> bool {
    matches!(
        (declaration.as_str(), arguments),
        (crate::prelude::OPTION_ID, [ResolvedType::Bytes])
            | (
                crate::prelude::RESULT_ID,
                [
                    ResolvedType::Bytes,
                    ResolvedType::I64
                        | ResolvedType::I32
                        | ResolvedType::Char
                        | ResolvedType::U8
                        | ResolvedType::Usize
                        | ResolvedType::F32
                        | ResolvedType::F64
                        | ResolvedType::Bool
                ]
            )
            | (
                crate::prelude::RESULT_ID,
                [
                    ResolvedType::I64
                        | ResolvedType::I32
                        | ResolvedType::U8
                        | ResolvedType::Usize
                        | ResolvedType::Char
                        | ResolvedType::F32
                        | ResolvedType::F64
                        | ResolvedType::Bool,
                    ResolvedType::Bytes
                ]
            )
            | (
                crate::prelude::RESULT_ID,
                [ResolvedType::Bytes, ResolvedType::Bytes]
            )
    )
}

pub(super) fn resolver_admits_flat_owned_byte_variant(
    declarations: &DeclarationIndex,
    ty: &ResolvedType,
) -> bool {
    if crate::iterator_ops::step_shape(declarations, ty) {
        return true;
    }
    let ResolvedType::Nominal {
        declaration,
        arguments,
    } = ty
    else {
        return false;
    };
    if admitted_owned_byte_prelude_instance(declaration, arguments) {
        return true;
    }
    if arguments.is_empty()
        && declarations
            .type_parameters(declaration)
            .is_some_and(|parameters| parameters.is_empty())
    {
        return declarations
            .variant_cases(declaration)
            .is_some_and(|cases| {
                cases
                    .iter()
                    .flat_map(|case| &case.fields)
                    .any(|field| field.ty == ResolvedType::Bytes)
                    && cases.iter().flat_map(|case| &case.fields).all(|field| {
                        field.ty == ResolvedType::Bytes || is_scalar_resolved_type(&field.ty)
                    })
            });
    }
    super::type_reachability::is_admitted_concrete_owned_byte_variant(declarations, ty)
}

pub(super) fn resolver_admits_flat_owned_string_variant(
    declarations: &DeclarationIndex,
    ty: &ResolvedType,
) -> bool {
    super::type_reachability::is_admitted_owned_string_variant(declarations, ty)
}

pub(super) fn resolver_admits_direct_owned_variant(
    declarations: &DeclarationIndex,
    ty: &ResolvedType,
) -> bool {
    resolver_admits_flat_owned_string_variant(declarations, ty)
        || super::collection_outcome::runtime_admitted(declarations, ty)
}

#[allow(dead_code)]
pub(super) fn resolver_admits_owned_variant(
    declarations: &DeclarationIndex,
    ty: &ResolvedType,
) -> bool {
    resolver_admits_flat_owned_byte_variant(declarations, ty)
        || resolver_admits_direct_owned_variant(declarations, ty)
}

