impl HirValidator<'_> {
    pub(super) fn finish_expr(
        &self,
        expression: &ResolvedExpr,
        ty: &ResolvedType,
        ownership: OwnershipMode,
    ) -> Result<(), Diagnostic> {
        self.require_type(&expression.ty, ty, "expression")?;
        if expression.ownership != ownership {
            return Err(hir_error(format!(
                "expression `{}` has inconsistent ownership",
                expression.id
            )));
        }
        Ok(())
    }
}

impl HirValidator<'_> {
    /// Float literals must stay finite so canonical source projection and
    /// every backend agree on the exact value; infinities and NaNs cannot be
    /// written as literals and hostile HIR is rejected here.
    pub(super) fn validate_finite_f32(&self, bits: u32) -> Result<(), Diagnostic> {
        if f32::from_bits(bits).is_finite() {
            Ok(())
        } else {
            Err(hir_error(
                "f32 literal bits are not a finite IEEE-754 value",
            ))
        }
    }

    pub(super) fn validate_finite_f64(&self, bits: u64) -> Result<(), Diagnostic> {
        if f64::from_bits(bits).is_finite() {
            Ok(())
        } else {
            Err(hir_error(
                "f64 literal bits are not a finite IEEE-754 value",
            ))
        }
    }
}

#[cfg(test)]
mod type_admission_tests {
    use super::*;
    fn fixture() -> ResolvedProgram {
        let source = crate::parse(
            r#"module admission.frames;
@id("admission.row") record Row { @id("admission.field") field: i64, }
@id("admission.box") record Box<T> { @id("admission.box.field") field: T, }
@id("admission.main") fn main() -> i64 { 0 }
"#,
            std::path::Path::new("type-admission.spx"),
        )
        .unwrap();
        crate::hir::resolve(&source).unwrap()
    }
    fn verdict(result: Result<(), Diagnostic>) -> Result<(), (String, String)> {
        result.map_err(|error| (error.code.to_string(), error.message.into_owned()))
    }
    fn nominal(id: &str, arguments: Vec<ResolvedType>) -> ResolvedType {
        ResolvedType::Nominal {
            declaration: DeclarationId::new(id),
            arguments,
        }
    }
    #[test]
    fn inline_and_lazy_type_admission_preserve_saved_eager_verdicts() {
        let mut program = fixture();
        let mut types = vec![
            ResolvedType::Never,
            ResolvedType::Unit,
            ResolvedType::I64,
            ResolvedType::I32,
            ResolvedType::Char,
            ResolvedType::U8,
            ResolvedType::Usize,
            ResolvedType::ArrayU8(17),
            ResolvedType::F32,
            ResolvedType::F64,
            ResolvedType::Bool,
            ResolvedType::String,
            ResolvedType::Bytes,
            ResolvedType::Str,
            ResolvedType::SliceU8,
            ResolvedType::StringMap,
            ResolvedType::OnceFunction,
            ResolvedType::OnceFunctionI64,
            ResolvedType::OnceFunctionI64Pair,
            ResolvedType::MutFunctionI64,
            ResolvedType::TypeParameter {
                owner: DeclarationId::new("admission.box"),
                index: 0,
            },
            nominal("missing", vec![]),
            nominal("admission.row", vec![]),
            nominal("admission.box", vec![]),
            nominal("admission.row", vec![ResolvedType::Bytes]),
            nominal("admission.box", vec![ResolvedType::Bytes]),
            nominal("admission.box", vec![ResolvedType::String]),
            nominal("admission.box", vec![ResolvedType::I64]),
            nominal("admission.box", vec![ResolvedType::Str]),
        ];
        types.push(ResolvedType::Function {
            parameters: vec![ResolvedType::I64],
            result: Box::new(ResolvedType::Bool),
        });
        types.push(ResolvedType::Function {
            parameters: vec![ResolvedType::Bytes],
            result: Box::new(ResolvedType::Bytes),
        });
        for cached in [false, true] {
            if cached {
                let mut facts = program.declarations.type_facts(&ResolvedType::I64).unwrap();
                facts.copy = false;
                facts.layout_key = "arbitrary hostile cached layout".repeat(32);
                program
                    .declarations
                    .type_facts_by_id
                    .insert("i64".into(), facts.clone());
                program
                    .declarations
                    .type_facts_by_id
                    .insert(nominal("admission.row", vec![]).identity_key(), facts);
            }
            let validator = HirValidator::new(&program).unwrap();
            let missing = validator
                .validate_type(&nominal("missing", vec![]))
                .unwrap_err();
            assert_eq!(missing.code, "SPX-H006");
            assert_eq!(
                missing.message,
                "nominal type `missing` is not a resolved type declaration"
            );
            let arity = validator
                .validate_type(&nominal("admission.box", vec![]))
                .unwrap_err();
            assert_eq!(arity.code, "SPX-H006");
            assert_eq!(
                arity.message,
                "nominal type `admission.box` has incorrect argument arity"
            );
            for ty in &types {
                assert_eq!(
                    verdict(validator.validate_type(ty)),
                    verdict(validator.validate_type_eager_oracle(ty))
                );
                for ownership in [
                    OwnershipMode::Value,
                    OwnershipMode::Own,
                    OwnershipMode::Borrow,
                    OwnershipMode::Shared,
                ] {
                    assert_eq!(
                        verdict(validator.validate_declared_ownership(ty, ownership)),
                        verdict(
                            validator.validate_declared_ownership_full_facts_oracle(ty, ownership)
                        )
                    );
                }
            }
        }
    }
    #[test]
    fn inline_type_admission_allocations_are_literal_and_drop_settles() {
        let program = fixture();
        let validator = HirValidator::new(&program).unwrap();
        let scalar = ResolvedType::I64;
        let (_, scalar_metrics) = crate::test_allocation_observer::measure(|| {
            validator.validate_type(&scalar).unwrap();
            validator
                .validate_declared_ownership(&scalar, OwnershipMode::Value)
                .unwrap();
        });
        assert!(!scalar_metrics.invalid);
        assert_eq!(
            (
                scalar_metrics.allocations,
                scalar_metrics.allocated,
                scalar_metrics.live
            ),
            (0, 0, 0)
        );
        let nominal = nominal("admission.row", vec![]);
        let (old, old_metrics) = crate::test_allocation_observer::measure(|| {
            validator.validate_type_eager_oracle(&nominal)
        });
        let (actual, metrics) =
            crate::test_allocation_observer::measure(|| validator.validate_type(&nominal));
        assert!(old.is_ok() && actual.is_ok());
        for m in [old_metrics, metrics] {
            assert!(!m.invalid);
            assert_eq!(m.live, 0);
            assert_eq!(m.allocated, m.freed);
        }
        assert!(metrics.allocations < old_metrics.allocations);
        assert!(metrics.allocated < old_metrics.allocated);
    }
}

//! Validation-local borrowed facts for exact zero-argument nominal types.
//!
//! The immutable Program retains the identities and facts. Only sorted reference
//! metadata is owned here; validator clones share that metadata. Other types and
//! absent retained entries keep the original owning/recomputation path.
use super::*;
use std::borrow::Cow;
use std::cell::OnceCell;
use std::fmt::Write as _;
use std::sync::Arc;

type Entry<'a> = (&'a DeclarationId, &'a TypeFacts);
type SharedEntries<'a> = Arc<Vec<Entry<'a>>>;

// Arc<Vec<_>> has the same audited two-counter/three-word carrier layout as
// Arc<String>. The separate Vec backing is charged below, including excess.
const _: () = assert!(std::mem::size_of::<Vec<Entry<'static>>>() == std::mem::size_of::<String>());
const _: () =
    assert!(std::mem::align_of::<Vec<Entry<'static>>>() == std::mem::align_of::<String>());
const CARRIER_BYTES: usize = ExpressionId::SHARED_ALLOCATION_CARRIER_BYTES;

#[derive(Clone, Default)]
pub(super) struct Lookup<'a> {
    entries: OnceCell<Option<SharedEntries<'a>>>,
}

fn refused() -> Diagnostic {
    hir_error("nominal type-facts lookup metadata exceeds the active validation budget")
}

fn reserve(bytes: usize) -> Result<(), Diagnostic> {
    crate::bounded_output::reserve_active_required(bytes)
        .then_some(())
        .ok_or_else(refused)
}

fn eligible(program: &ResolvedProgram, declaration: &ResolvedTypeDeclaration) -> bool {
    declaration.type_parameters.is_empty()
        && program
            .declarations
            .type_parameters(&declaration.id)
            .is_some_and(|parameters| parameters.is_empty())
}

fn nominal_key(identity: &DeclarationId) -> Result<String, Diagnostic> {
    let length = identity.as_str().len();
    let mut remaining = length;
    let mut digits = 1usize;
    while remaining >= 10 {
        remaining /= 10;
        digits += 1;
    }
    // Exact identity_key spelling: nominal:<byte-length>:<identity>:0:.
    let bytes = length
        .checked_add(digits)
        .and_then(|bytes| bytes.checked_add(11))
        .ok_or_else(refused)?;
    reserve(bytes)?;
    let mut key = String::with_capacity(bytes);
    reserve(key.capacity() - bytes)?;
    write!(key, "nominal:{length}:{}:0:", identity.as_str()).map_err(|_| refused())?;
    Ok(key)
}

impl<'a> Lookup<'a> {
    fn prepare(program: &'a ResolvedProgram) -> Result<Option<SharedEntries<'a>>, Diagnostic> {
        let count = program
            .types
            .iter()
            .filter(|declaration| eligible(program, declaration))
            .count();
        if count == 0 {
            return Ok(None);
        }
        let bytes = count
            .checked_mul(std::mem::size_of::<Entry<'a>>())
            .ok_or_else(refused)?;
        reserve(bytes.checked_add(CARRIER_BYTES).ok_or_else(refused)?)?;
        let mut entries = Vec::with_capacity(count);
        let excess = entries
            .capacity()
            .checked_sub(count)
            .and_then(|slots| slots.checked_mul(std::mem::size_of::<Entry<'a>>()))
            .ok_or_else(refused)?;
        reserve(excess)?;
        for declaration in program
            .types
            .iter()
            .filter(|declaration| eligible(program, declaration))
        {
            let key = nominal_key(&declaration.id)?;
            if let Some(facts) = program.declarations.type_facts_by_id.get(&key) {
                entries.push((&declaration.id, facts));
            }
        }
        if entries.is_empty() {
            return Ok(None);
        }
        entries.sort_unstable_by(|left, right| left.0.cmp(right.0));
        Ok(Some(Arc::new(entries)))
    }

    fn get(
        &self,
        program: &'a ResolvedProgram,
        ty: &ResolvedType,
    ) -> Result<Option<&'a TypeFacts>, Diagnostic> {
        let ResolvedType::Nominal {
            declaration,
            arguments,
        } = ty
        else {
            return Ok(None);
        };
        if !arguments.is_empty() {
            return Ok(None);
        }
        if self.entries.get().is_none() {
            // Do not build unrelated metadata for an unknown or generic
            // zero-argument request. Prepared entries already prove eligibility.
            if !program
                .declarations
                .type_parameters(declaration)
                .is_some_and(|parameters| parameters.is_empty())
            {
                return Ok(None);
            }
            self.entries
                .set(Self::prepare(program)?)
                .map_err(|_| hir_error("nominal facts lookup initialized twice"))?;
        }
        let Some(entries) = self.entries.get().and_then(Option::as_ref) else {
            return Ok(None);
        };
        Ok(entries
            .binary_search_by(|entry| entry.0.cmp(declaration))
            .ok()
            .map(|index| entries[index].1))
    }

    #[cfg(test)]
    pub(super) fn owned_capacity(&self) -> usize {
        self.entries
            .get()
            .and_then(Option::as_ref)
            .map_or(0, |entries| {
                CARRIER_BYTES + entries.capacity() * std::mem::size_of::<Entry<'a>>()
            })
    }
}

impl<'a> HirValidator<'a> {
    pub(super) fn borrowed_type_facts(
        &self,
        ty: &ResolvedType,
    ) -> Result<Option<Cow<'a, TypeFacts>>, Diagnostic> {
        if let Some(facts) = self.nominal_facts.get(self.program, ty)? {
            Ok(Some(Cow::Borrowed(facts)))
        } else {
            Ok(self.program.declarations.type_facts(ty).map(Cow::Owned))
        }
    }
}

#[cfg(test)]
mod tests;

use super::*;

const SOURCE: &str = r#"
module test.nominal_facts;
@id("facts.class") class Class { @id("facts.class.value") value: i64, }
@id("facts.record") record Record { @id("facts.record.value") value: i64, }
@id("facts.variant") variant Variant {
    @id("facts.variant.value") Value { @id("facts.variant.field") value: i64, },
}
@id("facts.owned") record Owned { @id("facts.owned.payload") payload: Bytes, }
@id("facts.generic") record Generic<T> { @id("facts.generic.value") value: T, }
@id("app.main") fn main() -> i64 { 0 }
"#;

fn program() -> ResolvedProgram {
    let source = crate::parse(SOURCE, std::path::Path::new("nominal-facts.spx")).unwrap();
    crate::hir::resolve(&source).unwrap()
}

fn nominal(identity: &str, arguments: Vec<ResolvedType>) -> ResolvedType {
    ResolvedType::Nominal {
        declaration: DeclarationId::new(identity),
        arguments,
    }
}

#[test]
fn nominal_facts_borrow_exact_retained_values_and_keep_wire_unchanged() {
    let program = program();
    let wire = crate::cache_codec::encode(&program).unwrap();
    let validator = HirValidator::new(&program).unwrap();
    assert!(validator.nominal_facts.entries.get().is_none());
    for identity in [
        "facts.class",
        "facts.record",
        "facts.variant",
        "facts.owned",
    ] {
        let ty = nominal(identity, Vec::new());
        let expected = program.declarations.type_facts(&ty).unwrap();
        let actual = validator.borrowed_type_facts(&ty).unwrap().unwrap();
        assert_eq!(actual.as_ref(), &expected);
        let Cow::Borrowed(actual) = actual else {
            panic!("zero-argument retained facts were cloned")
        };
        assert!(std::ptr::eq(
            actual,
            &program.declarations.type_facts_by_id[&ty.identity_key()]
        ));
    }
    assert_eq!(crate::cache_codec::encode(&program).unwrap(), wire);
    assert!(validator.nominal_facts.owned_capacity() > 0);
}

#[test]
fn nominal_facts_keep_generic_missing_and_unknown_fallbacks_exact() {
    let mut program = program();
    let missing = nominal("facts.record", Vec::new());
    program
        .declarations
        .type_facts_by_id
        .remove(&missing.identity_key());
    // An invalid zero-argument generic cache entry must not become eligible.
    let empty_generic = nominal("facts.generic", Vec::new());
    let forged = program.declarations.type_facts(&ResolvedType::I64).unwrap();
    program
        .declarations
        .type_facts_by_id
        .insert(empty_generic.identity_key(), forged);
    let lazy = Lookup::default();
    let ((), overflow, used) = crate::bounded_output::with_limit_usage(0, || {
        assert!(lazy.get(&program, &empty_generic).unwrap().is_none());
        assert!(lazy
            .get(&program, &nominal("facts.unknown", Vec::new()))
            .unwrap()
            .is_none());
        assert!(lazy.entries.get().is_none());
    });
    assert!(!overflow);
    assert_eq!(used, 0);
    let validator = HirValidator::new(&program).unwrap();
    let generic_i64 = nominal("facts.generic", vec![ResolvedType::I64]);
    let generic_u8 = nominal("facts.generic", vec![ResolvedType::U8]);
    for ty in [
        missing,
        empty_generic,
        generic_i64.clone(),
        generic_u8.clone(),
        nominal(crate::prelude::VEC_ID, vec![ResolvedType::I64]),
        nominal(crate::prelude::BOX_ID, vec![ResolvedType::U8]),
        nominal("facts.unknown", Vec::new()),
        ResolvedType::TypeParameter {
            owner: DeclarationId::new("facts.generic"),
            index: 0,
        },
    ] {
        let expected = program.declarations.type_facts(&ty);
        let actual = validator.borrowed_type_facts(&ty).unwrap();
        assert_eq!(actual.as_deref(), expected.as_ref());
        assert!(!matches!(actual, Some(Cow::Borrowed(_))));
    }
    assert_ne!(
        program
            .declarations
            .type_facts(&generic_i64)
            .unwrap()
            .layout_key,
        program
            .declarations
            .type_facts(&generic_u8)
            .unwrap()
            .layout_key
    );
}

#[test]
fn nominal_facts_do_not_recompute_unused_malformed_declarations_or_alias_generic_metadata() {
    let mut program = program();
    let record = nominal("facts.record", Vec::new());
    let key = record.identity_key();
    let expected = program.declarations.type_facts_by_id[&key].clone();
    // The retained entry still exists, but independently reconstructing this
    // hostile declaration's recursive facts must fail. Preparation only borrows.
    program
        .declarations
        .record_fields
        .get_mut(&DeclarationId::new("facts.record"))
        .unwrap()[0]
        .ty = record.clone();
    let generic = nominal("facts.generic", Vec::new());
    program
        .declarations
        .type_facts_by_id
        .insert(generic.identity_key(), expected.clone());
    program
        .types
        .iter_mut()
        .find(|declaration| declaration.id.as_str() == "facts.generic")
        .unwrap()
        .type_parameters
        .clear();
    let lookup = Lookup::default();
    assert_eq!(lookup.get(&program, &record).unwrap(), Some(&expected));
    assert!(lookup.get(&program, &generic).unwrap().is_none());
    assert!(program.declarations.recompute_type_facts(&record).is_none());
}

#[test]
fn nominal_facts_preserve_stale_cached_fact_rejection() {
    let mut program = program();
    let ty = nominal("facts.record", Vec::new());
    let key = ty.identity_key();
    program
        .declarations
        .type_facts_by_id
        .get_mut(&key)
        .unwrap()
        .layout_key
        .push_str(".stale");
    let validator = HirValidator::new(&program).unwrap();
    let borrowed = validator.borrowed_type_facts(&ty).unwrap().unwrap();
    assert_eq!(
        borrowed.as_ref(),
        &program.declarations.type_facts(&ty).unwrap()
    );
    assert_ne!(
        borrowed.as_ref(),
        &program.declarations.recompute_type_facts(&ty).unwrap()
    );
    let error = validate_core(&program).unwrap_err();
    assert_eq!(error.code, "SPX-H006");
    assert_eq!(
        error.message,
        "record `facts.record` has invalid or stale recursive type facts"
    );
}

#[test]
fn nominal_facts_repeated_lookup_and_shared_clone_need_no_temporary_key_budget() {
    let program = program();
    let ty = nominal("facts.record", Vec::new());
    let lookup = Lookup::default();
    let expected = lookup.get(&program, &ty).unwrap().unwrap();
    let capacity = lookup.owned_capacity();
    let ((), overflow, used) = crate::bounded_output::with_limit_usage(0, || {
        let cloned = lookup.clone();
        assert_eq!(cloned.owned_capacity(), capacity);
        assert!(Arc::ptr_eq(
            lookup.entries.get().unwrap().as_ref().unwrap(),
            cloned.entries.get().unwrap().as_ref().unwrap()
        ));
        for _ in 0..64 {
            assert!(std::ptr::eq(
                cloned.get(&program, &ty).unwrap().unwrap(),
                expected
            ));
        }
    });
    assert!(!overflow);
    assert_eq!(used, 0);
}

#[test]
fn nominal_facts_preparation_charges_metadata_and_refuses_one_short_or_floor() {
    let program = program();
    let ty = nominal("facts.record", Vec::new());
    let (lookup, overflow, used) = crate::bounded_output::with_limit_usage(usize::MAX, || {
        let lookup = Lookup::default();
        assert!(lookup.get(&program, &ty).unwrap().is_some());
        lookup
    });
    assert!(!overflow);
    assert!(used >= lookup.owned_capacity());
    assert!(used > 0);
    let (result, overflow) =
        crate::bounded_output::with_limit(used, || Lookup::default().get(&program, &ty));
    assert!(!overflow);
    assert!(result.unwrap().is_some());
    let (result, overflow) =
        crate::bounded_output::with_limit(used - 1, || Lookup::default().get(&program, &ty));
    assert!(overflow);
    assert_eq!(result.unwrap_err().code, "SPX-H006");
    let (result, overflow) = crate::bounded_output::with_limit(used, || {
        assert!(crate::bounded_output::set_active_floor(1));
        Lookup::default().get(&program, &ty)
    });
    assert!(overflow);
    assert_eq!(result.unwrap_err().code, "SPX-H006");
}

#[test]
fn nominal_facts_zero_argument_key_matches_canonical_bytes_without_identity_clone() {
    for identity in ["x", "colon:id", "unicode.λ", "long.identity.with.parts"] {
        let ty = nominal(identity, Vec::new());
        let ResolvedType::Nominal { declaration, .. } = &ty else {
            unreachable!()
        };
        assert_eq!(nominal_key(declaration).unwrap(), ty.identity_key());
    }
}

#[test]
fn nominal_facts_private_forecast_covers_prelude_and_metadata_key_coexistence() {
    let prelude = crate::prelude::declarations()
        .iter()
        .filter(|declaration| declaration.type_parameters.is_empty())
        .map(|declaration| declaration.stable_id.as_str())
        .collect::<Vec<_>>();
    assert_eq!(
        prelude,
        crate::private_capacity_contract::ZERO_ARGUMENT_FACT_PRELUDE_IDS
    );
    let source = crate::parse(SOURCE, std::path::Path::new("nominal-facts.spx")).unwrap();
    let program = crate::hir::resolve(&source).unwrap();
    let ty = nominal("facts.record", Vec::new());
    let lookup = Lookup::default();
    assert!(lookup.get(&program, &ty).unwrap().is_some());
    let maximum_key = program
        .types
        .iter()
        .filter(|declaration| eligible(&program, declaration))
        .map(|declaration| nominal_key(&declaration.id).unwrap().capacity())
        .max()
        .unwrap();
    let upper = crate::private_capacity_contract::nominal_facts_lookup_upper(&source).unwrap();
    assert!(lookup.owned_capacity() + maximum_key <= upper);
}

