#[derive(Clone, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum ResolvedType {
    /// Compiler-owned absence of normal completion; never a stored/ABI value.
    Never,
    /// A retained affine zero-argument, i64-result callable.
    OnceFunction,
    OnceFunctionI64,
    OnceFunctionI64Pair,
    /// Same-thread transactional i64 callback; unlike ordinary function
    /// values it owns one mutable receiver state cell.
    MutFunctionI64,
    Function {
        parameters: Vec<ResolvedType>,
        result: Box<ResolvedType>,
    },
    Unit,
    I64,
    /// A checked signed 32-bit integer.
    I32,
    /// One Unicode scalar value.
    Char,
    /// One unsigned 8-bit integer value.
    U8,
    /// A target-independent checked unsigned 64-bit semantic integer.
    Usize,
    /// Inline Copy byte storage with exact target-independent length.
    ArrayU8(u32),
    /// IEEE-754 single precision.
    F32,
    /// IEEE-754 double precision.
    F64,
    Bool,
    /// An owned heap UTF-8 string value; never `Copy`.
    String,
    /// Uniquely owned immutable bytes. This needs drop but is not a resource.
    Bytes,
    /// A non-owning UTF-8 view rooted in the current invocation.
    Str,
    /// A non-owning byte view rooted in the current invocation.
    SliceU8,
    /// String Collections v1: the uniquely owned `Map<string, i64>` carrier.
    /// It needs drop, is never `Copy`, and is admitted only for local
    /// bindings threaded through the compiler-owned `map_*` operations.
    StringMap,
    TypeParameter {
        owner: DeclarationId,
        index: u32,
    },
    Nominal {
        declaration: DeclarationId,
        arguments: Vec<ResolvedType>,
    },
}

impl ResolvedType {
    pub fn is_callable(&self) -> bool {
        self.is_once_function() || self.is_mut_function() || matches!(self, Self::Function { .. })
    }

    pub fn is_mut_function(&self) -> bool {
        matches!(self, Self::MutFunctionI64)
    }

    pub fn is_once_function(&self) -> bool {
        matches!(
            self,
            Self::OnceFunction | Self::OnceFunctionI64 | Self::OnceFunctionI64Pair
        )
    }

    pub fn is_compiler_i64_result(&self) -> bool {
        matches!(self, Self::Nominal { declaration, arguments }
            if declaration.as_str() == crate::prelude::RESULT_ID
                && arguments == &[Self::I64, Self::I64])
    }

    /// Canonical ownership classification shared by the resolver, cleanup
    /// builder, hostile validator, and backends. Unique ownership is not the
    /// same fact as containing an opaque resource.
    pub fn is_uniquely_owned(&self) -> bool {
        matches!(
            self,
            Self::String
                | Self::Bytes
                | Self::OnceFunction
                | Self::OnceFunctionI64
                | Self::OnceFunctionI64Pair
                | Self::MutFunctionI64
        ) || crate::map_ops::is_collection(self)
    }
    pub fn is_compiler_byte_option(&self) -> bool {
        matches!(
            self,
            Self::Nominal {
                declaration,
                arguments,
            } if declaration.as_str() == crate::prelude::OPTION_ID
                && arguments.as_slice() == [ResolvedType::U8]
        )
    }

    pub fn nominal_id(&self) -> Option<&DeclarationId> {
        match self {
            Self::Nominal { declaration, .. } => Some(declaration),
            Self::Function { .. }
            | Self::OnceFunction
            | Self::OnceFunctionI64
            | Self::OnceFunctionI64Pair
            | Self::MutFunctionI64
            | Self::Never
            | Self::Unit
            | Self::I64
            | Self::I32
            | Self::Char
            | Self::U8
            | Self::Usize
            | Self::ArrayU8(_)
            | Self::F32
            | Self::F64
            | Self::Bool
            | Self::String
            | Self::Bytes
            | Self::Str
            | Self::SliceU8
            | Self::StringMap
            | Self::TypeParameter { .. } => None,
        }
    }

    /// A name-independent key suitable as an input to future layout hashing.
    pub fn identity_key(&self) -> String {
        // Zero-argument nominal keys need no traversal or child-key storage.
        // Keep the exact length-delimited encoding used by the general path.
        if let Self::Nominal {
            declaration,
            arguments,
        } = self
        {
            if arguments.is_empty() {
                return format!("nominal:{}:{}:0:", declaration.as_str().len(), declaration);
            }
        }
        enum Frame<'a> {
            Enter(&'a ResolvedType),
            Finish(&'a DeclarationId, usize),
            FinishFunction(usize),
        }
        let mut frames = vec![Frame::Enter(self)];
        let mut keys = Vec::<String>::new();
        while let Some(frame) = frames.pop() {
            match frame {
                Frame::Enter(ty) => match ty {
                    Self::Function { parameters, result } => {
                        frames.push(Frame::FinishFunction(parameters.len()));
                        frames.push(Frame::Enter(result));
                        frames.extend(parameters.iter().rev().map(Frame::Enter));
                    }
                    Self::OnceFunction => keys.push("fn-once:bytes:i64:v1".to_owned()),
                    Self::OnceFunctionI64 => keys.push("fn-once:bytes+i64:i64:v2".to_owned()),
                    Self::OnceFunctionI64Pair => {
                        keys.push("fn-once:bytes+i64+i64:i64:v3".to_owned())
                    }
                    Self::MutFunctionI64 => keys.push("fn-mut:i64+i64:i64:v1".to_owned()),
                    Self::Never => keys.push("never:lexical-exit:v1".to_owned()),
                    Self::Unit => keys.push("unit".to_owned()),
                    Self::I64 => keys.push("i64".to_owned()),
                    Self::I32 => keys.push("i32".to_owned()),
                    Self::Char => keys.push("char".to_owned()),
                    Self::U8 => keys.push("u8".to_owned()),
                    Self::Usize => keys.push("usize".to_owned()),
                    Self::ArrayU8(length) => keys.push(format!("array:u8:{length}")),
                    Self::F32 => keys.push("f32".to_owned()),
                    Self::F64 => keys.push("f64".to_owned()),
                    Self::Bool => keys.push("bool".to_owned()),
                    Self::String => keys.push("string".to_owned()),
                    Self::Bytes => keys.push("bytes".to_owned()),
                    Self::Str => keys.push("str".to_owned()),
                    Self::SliceU8 => keys.push("slice-u8".to_owned()),
                    Self::StringMap => keys.push("map:string:i64:v1".to_owned()),
                    Self::TypeParameter { owner, index } => keys.push(format!(
                        "parameter:{}:{}:{index}",
                        owner.as_str().len(),
                        owner
                    )),
                    Self::Nominal {
                        declaration,
                        arguments,
                    } => {
                        frames.push(Frame::Finish(declaration, arguments.len()));
                        frames.extend(arguments.iter().rev().map(Frame::Enter));
                    }
                },
                Frame::FinishFunction(count) => {
                    let split = keys
                        .len()
                        .checked_sub(count + 1)
                        .expect("function key children retained");
                    let mut key = format!("function:v1:{count}:");
                    for child in keys.drain(split..) {
                        write!(key, "{}:{child}", child.len()).expect("string write");
                    }
                    keys.push(key);
                }
                Frame::Finish(declaration, count) => {
                    let split = keys
                        .len()
                        .checked_sub(count)
                        .expect("type-key traversal has one result per argument");
                    let mut encoded = crate::bounded_output::CappedString::new();
                    for key in keys.drain(split..) {
                        write!(encoded, "{}:{key}", key.len())
                            .expect("writing to a string cannot fail");
                    }
                    keys.push(format!(
                        "nominal:{}:{}:{}:{}",
                        declaration.as_str().len(),
                        declaration,
                        count,
                        encoded.into_string()
                    ));
                }
            }
        }
        keys.pop().expect("a type always produces an identity key")
    }
}

