        let scalar = ResolvedType::I64;
        let (_, scalar_metrics) = crate::test_allocation_observer::measure(|| {
            validator.validate_type(&scalar).unwrap();
            validator
                .validate_declared_ownership(&scalar, OwnershipMode::Value)
                .unwrap();
        });
        assert!(!scalar_metrics.invalid);
        assert_eq!(
            (
                scalar_metrics.allocations,
                scalar_metrics.allocated,
                scalar_metrics.live
            ),
            (0, 0, 0)
        );
        let nominal = nominal("admission.row", vec![]);
        let (old, old_metrics) = crate::test_allocation_observer::measure(|| {
            validator.validate_type_eager_oracle(&nominal)
        });
        let (actual, metrics) =
            crate::test_allocation_observer::measure(|| validator.validate_type(&nominal));
        assert!(old.is_ok() && actual.is_ok());
        for m in [old_metrics, metrics] {
            assert!(!m.invalid);
            assert_eq!(m.live, 0);
            assert_eq!(m.allocated, m.freed);
        }
        assert!(metrics.allocations < old_metrics.allocations);
        assert!(metrics.allocated < old_metrics.allocated);
    }
}

//! Bounded inline scratch, with the complete ordinary Vec spill path.
//! This bound selects storage only; no type, depth or argument is rejected.
pub(super) struct Stack<T, const N: usize> {
    inline: [Option<T>; N],
    len: usize,
    spill: Vec<T>,
}
impl<T, const N: usize> Stack<T, N> {
    pub(super) fn new() -> Self {
        Self {
            inline: std::array::from_fn(|_| None),
            len: 0,
            spill: Vec::new(),
        }
    }
    pub(super) fn push(&mut self, value: T) {
        if self.spill.is_empty() && self.len < N {
            self.inline[self.len] = Some(value);
            self.len += 1;
        } else {
            self.spill.push(value);
        }
    }
    pub(super) fn pop(&mut self) -> Option<T> {
        if let Some(value) = self.spill.pop() {
            return Some(value);
        }
        if self.len == 0 {
            return None;
        }
        self.len -= 1;
        self.inline[self.len].take()
    }
}
